function removerDuplicados(registros, campo) {
  const vistos = new Set()
  const saida = []

  for (const registro of registros) {
    const valor = registro[campo]
    if (valor === undefined || valor === null) {
      saida.push(registro)
      continue
    }
    if (vistos.has(valor)) continue
    vistos.add(valor)
    saida.push(registro)
  }

  return saida
}

