const ORDEM = { urgente: 0, alta: 1, media: 2, baixa: 3 }

function ordenarFila(tickets) {
  return [...tickets].sort((a, b) => {
    const pa = ORDEM[a.prioridade] ?? 99
    const pb = ORDEM[b.prioridade] ?? 99
    if (pa !== pb) return pa - pb
    return String(a.criadoEm).localeCompare(String(b.criadoEm))
  })
}

