function criarHistorico(limite) {
  const maximo = Math.max(1, limite)
  const acoes = []

  return {
    registrar(acao) {
      acoes.push(acao)
      if (acoes.length > maximo) acoes.shift()
    },
    desfazer() {
      return acoes.length === 0 ? null : acoes.pop()
    },
    tamanho() {
      return acoes.length
    },
  }
}

