function montarArvore(linhas) {
  const porId = new Map()
  for (const linha of linhas) {
    porId.set(linha.id, { id: linha.id, nome: linha.nome, filhos: [] })
  }

  const raizes = []
  for (const linha of linhas) {
    const no = porId.get(linha.id)
    const pai = linha.paiId === null ? undefined : porId.get(linha.paiId)
    // Pai ausente na lista: o nó não pode sumir, então vira raiz.
    if (pai) pai.filhos.push(no)
    else raizes.push(no)
  }

  return raizes
}
